  accounts() {
    return [...this.#accounts.keys()].sort().map((id) => this.#accounts.get(id));
  }

  #requireAccount(accountId) {
    const account = this.#accounts.get(accountId);
    if (!account) throw new LedgerError('UNKNOWN_ACCOUNT', `unknown account: ${accountId}`);
    return account;
  }

  #expose(record) {
    return Object.freeze({
      id: record.id,
      at: record.at,
      seq: record.seq,
      memo: record.memo,
      lines: record.lines,
      reverses: record.reverses,
      reversedBy: record.reversedBy,
