  let original = null;
  if (reversesId !== null) {
    original = this.#entries.get(reversesId);
    if (at < original.at) {
      throw new LedgerError('BAD_TIME', 'reversal must not precede its entry');
    }
  }

  const seq = this.#nextSeq;
  this.#nextSeq += 1;
  const record = {
    id,
    at,
    seq,
    memo,
    lines: Object.freeze(validatedLines),
    reverses: reversesId,
    reversedBy: null,
  };
  this.#entries.set(id, record);
  this.#order.push(record);
  if (original) {
    original.reversedBy = id;
  }
  return this.#expose(record);
}

